import re
from collections import Counter,defaultdict
src=open('net_stdospdb.h',errors='replace').read()
blocks=re.findall(r'\{\s*\.name\s*=(.*?)\n    \},', src, re.S)
ents=[]
for b in blocks:
    d={}
    for k in ('name','uri','uri_index'):
        m=re.search(r'\.%s\s*=\s*"([^"]*)"'%k,b); d[k]=m.group(1) if m else ''
    for k in ('mode','iss_build'):
        m=re.search(r'\.%s\s*=\s*([A-Za-z0-9_]+)'%k,b); d[k]=m.group(1) if m else ''
    ents.append(d)
print("total:",len(ents), Counter(e['mode'] for e in ents), Counter(e['iss_build'] for e in ents))

# apply the overrides found in net_stdospfdb_setup.c
scalars={"stdospdb/ospfASBdrRtrStatus","stdospdb/ospfTOSSupport","stdospdb/ospfExtLsdbLimit",
         "stdospdb/ospfMulticastExtensions","stdospdb/ospfExitOverflowInterval","stdospdb/ospfDemandExtensions"}
tables={"stdospdb/ospfStubAreaTable/","stdospdb/ospfAreaRangeTable/","stdospdb/ospfHostTable/"}
flipped=[]
for e in ents:
    hit = e['uri'] in scalars or e['uri'] in tables or (e['uri']=="stdospdb/ospfAreaTable/" and e['uri_index']=="ospfAuthType")
    if hit and e['mode']=='HANDLER_CAN_RWRITE':
        flipped.append(e)
print("\nRW->RO flipped by setup:",len(flipped))
c=Counter(e['uri'] for e in flipped)
for u,n in sorted(c.items()): print("  %-40s %d"%(u,n))
ro=sum(1 for e in ents if e['mode']=='HANDLER_CAN_RONLY')
print("\nstatic RO = %d   effective RO = %d  (+%d)"%(ro,ro+len(flipped),len(flipped)))
