                        (const char *)     file_val_str,
                        (const uint32_t )  strlen(file_val_str),
                                           oid_value,
                        ( uint32_t * )    &oid_value_len,
                        (const uint32_t )  MAX_OID_LEN ) != 0 )
            {
                LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "%% %s@%d parsing objIDString('%s') Error \n",
                    __func__, __LINE__, file_val_str );
                return IES_ERR;
            }

            memset(request->requestvb, 0, sizeof(netsnmp_variable_list));
            snmp_set_var_typed_value( request->requestvb, ASN_OBJECT_ID,
                    (const u_char *)oid_value, oid_value_len * sizeof(oid));
            break;
        case SNMP_DATA_TYPE_COUNTER64:
            tmp = utilString_strchr(file_val_str, strlen(file_val_str), '\'');
            if ( NULL != tmp ) 
            {
                *tmp = '\0';
            }
            if ( moxaSnmpHandle_UtilStringToCount64Value(file_val_str, strlen(file_val_str), &c64_value) != 0 )
            {
                LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "Error in %s line %d bin: %s\n", __func__, __LINE__, file_val_str);
                return IES_ERR;
            }
            snmp_set_var_typed_value(request->requestvb, ASN_COUNTER64, (u_char *)&c64_value, sizeof(c64_value));
            break;
        case SNMP_DATA_TYPE_NULL:
        case SNMP_DATA_TYPE_SEQUENCE:
        case SNMP_DATA_TYPE_IMP_OCTET_PRIM:
        case SNMP_DATA_TYPE_IMP_OBJECT_ID:
        case SNMP_DATA_TYPE_ROW_STATUS:
        default:
            LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "Error in %s line %d %d\n", __func__, __LINE__, entry->val_type);
            return IES_ERR;
    }
    snmp_set_var_objid(request->requestvb, file_oid, file_oid_len);
    return IES_NOERR;
#undef MAX_BIN_VALUE
}


