/**
 * @brief get oidEntry in fileBuff table

 * $param[in]    reqOIDList                   request oid
 * $param[in]    reqOIDListLen                the length of  request oid
 * $param[in]    tableEntry                   file buffer table entry
 * $param[in]    handleType                   FILE_BUF_GET_NEXT_ENTRY / FILE_BUF_GET_CURR_ENTRY
 * $param[out]   retIndex                     return table index

 * @returns
                 FILE_BUF_GET_ENTRY_SUCCESS   - get entry success
                 FILE_BUF_GET_ENTRY_MISS      - can't find the specific entry

 */
int32_t moxaSnmpHandle_UtilFileBuf_GetOIDEntry( const oid                          *reqOIDList,
                                                const uint32_t                      reqOIDListLen,
                                                const struct fileBuffer_tableEntry *tableEntry,
                                                const uint32_t                      handleType,
                                                uint32_t                           *retIndex )
{
    struct fileBuffer_oidEntry   *oidEntry = NULL;

    for ( int i = 0; i < tableEntry->file_oid_count; i++ )
    {
        oidEntry = tableEntry->file_oid_pool[i];
        if ( 0 == memcmp(reqOIDList, oidEntry->oid_list, sizeof(oid) * reqOIDListLen ) )
        {
            *retIndex = i;
            if ( handleType == FILE_BUF_GET_NEXT_ENTRY )
            {
                if(oidEntry->oid_len == reqOIDListLen)
                {
                    *retIndex = *retIndex + 1;
                }
            }
            return FILE_BUF_GET_ENTRY_SUCCESS;
        }
    }
    return FILE_BUF_GET_ENTRY_MISS;
}


/**
 * @brief update return buffer if oidEntry is correct

 * $param[in]    oidEntry                   oid entry
 * $param[out]   retOIDList                 return oid list
 * $param[out]   retOIDListLen              return oid list len
 * $param[out]   retOIDValue                return oid value

 * @returns      0 means success, others fail.

 */
int32_t moxaSnmpHandle_UtilFileBuf_UpdateReturnBuffer( const struct fileBuffer_oidEntry   *oidEntry,
                                                       oid                                *retOIDList,
                                                       int                                *retOIDListLen,
                                                       char                               *retOIDValue )
{
    if ( oidEntry->magic == IES_MAGIC_FILE_BUFFER_OID_ENTRY )
    {
        memcpy(retOIDList, oidEntry->oid_list, sizeof(oid) * oidEntry->oid_len);
        *retOIDListLen = oidEntry->oid_len;
        snprintf(retOIDValue, IES_MAX_FILE_BUF, "%s", oidEntry->buf);
        return 0;
    }
    return (-1);
}


