    {
        SNMPTrace ("SNMP:S Semaphore creation failed\r\n");
    }
    if (SNMP_GETNEXT_CREATE_SEMAPHORE () == OSIX_FAILURE)
    {
        SNMPTrace ("SNMP:S Semaphore creation failed\r\n");
    }

    /* Plan C: default this build to AgentX subagent mode, connecting to the
     * local net-snmp master on 127.0.0.1:705. Mirrors the nmh sequence of
     * SnxCliActivateAgentxSubagent (CLI "enable snmpsubagent master ip4
     * 127.0.0.1 port 705"). The default (empty) context set up by
     * SnxMainProtoInit is reused, so only addr/port/control are set here.
     * gi4SnmpAgentxSubAgtStatus is still SNMP_AGENTX_DISABLE at this point, so
     * the ENABLE transition fires SnxMainAgentxEnable()->SnxTransInit(); if the
     * master is not yet listening on :705, SNX_RECONNECT_TIMER retries until it
     * is. The IP is built as a host-order UINT4 then MEMCPY'd, exactly as the
     * CLI does, so the byte order round-trips identically. */
    {
        tSNMP_OCTET_STRING_TYPE MasterIp;
        UINT1                   au1Master[SNX_IP4_LEN];
        UINT4                   u4MasterIp = 0x7F000001;    /* 127.0.0.1, host order */

        MEMCPY (au1Master, &u4MasterIp, SNX_IP4_LEN);
        MasterIp.pu1_OctetList = au1Master;
        MasterIp.i4_Length = SNX_IP4_LEN;

        (VOID) nmhSetSnmpAgentxMasterAgentAddr (&MasterIp);
        (VOID) nmhSetSnmpAgentxMasterAgentPortNo (SNX_DEFAULT_MASTER_PORT);
        if (nmhSetSnmpAgentxSubAgentControl (SNMP_AGENTX_ENABLE) != SNMP_SUCCESS)
        {
            SNMPTrace ("Plan C: initial Agentx subagent enable deferred; "
                       "reconnect timer will retry\n");
        }
    }

    SNMP_INIT_COMPLETE (OSIX_SUCCESS);

