cd /home/moxa/sdc1/home/moxa/mds4xgl3/buildroot/dl/3rdparty_net_snmp/ies-auto-mibs && python3 - <<'PY'
import re,glob,collections
# 哪些 uri 被 setup 檔標上 REMAP 旗標
hits=collections.defaultdict(set)
for f in glob.glob('*.c'):
    L=open(f,errors='replace').read().splitlines()
    cur=None
    for l in L:
        m=re.search(r'COMPARE_URI\(entry->uri,\s*"([^"]*)"',l)
        if m: cur=m.group(1)
        if 'IES_FLAG_SNMP_ISS_REMAP' in l and cur:
            flag='MERGE' if 'MERGE' in l else 'TBL'
            hits[cur].add((flag,f))
print("=== 帶 ISS_REMAP 旗標的 uri(資料在別的 OID,不是同址 AgentX)===")
for u in sorted(hits):
    fl=','.join(sorted(set(x[0] for x in hits[u])))
    print("  %-46s %s" % (u,fl))
print("\n=== 這些 uri 對應的 OID root(它們的 Moxa OID)===")
ents=[]
for f in glob.glob('net_*.h'):
    for b in re.findall(r'\{\s*\.name\s*=(.*?)\n    \},', open(f,errors='replace').read(), re.S):
        u=re.search(r'\.uri\s*=\s*"([^"]*)"',b); o=re.search(r'\.oid_list\s*=\s*\{([^}]*)\}',b)
        if u and o: ents.append((u.group(1),'.'.join(x.strip() for x in o.group(1).split(','))))
for u in sorted(hits):
    oids=sorted(set('.'.join(o.split('.')[:12]) for uu,o in ents if uu.startswith(u)))
    print("  %-46s %s" % (u, ' '.join(oids) or '(無對應 entry)'))
PY
